}#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);

#define DE_RE_PIN 4
// Кнопки
const int BTN_UP = 2;
const int BTN_DOWN = 3;

// Таблица частот из даташита FS1264R: [диапазон FR1..FR8][канал CH1..CH8]
const long FREQ[8][8] = {
  {1920,1960,2000,2040,2080,2120,2160,2200}, // FR1: S=000
  {1900,1940,1980,2020,2060,2100,2140,2180}, // FR2: S=001
  {1740,1760,1780,1800,1820,1840,1860,1880}, // FR3: S=010
  {1720,1740,1760,1780,1800,1820,1840,1860}, // FR4: S=011
  {1420,1460,1500,1540,1580,1620,1660,1700}, // FR5: S=100
  {1400,1440,1480,1520,1560,1600,1640,1680}, // FR6: S=101
  {1100,1140,1180,1220,1260,1300,1340,1380}, // FR7: S=110
  {1080,1120,1160,1200,1240,1280,1320,1360}  // FR8: S=111
};
const char* BAND_NAMES[8] = {"FR1","FR2","FR3","FR4","FR5","FR6","FR7","FR8"};

int ch = 0;               // 0..63: старшие 3 бита — диапазон, младшие — канал
unsigned long lastSend = 0;
bool needRedraw = true;

void setup() {
  Serial.begin(115200);          // отладка на ПК
  Serial1.begin(9600);           // RS-485
  pinMode(DE_RE_PIN, OUTPUT);
  digitalWrite(DE_RE_PIN, LOW);  // по умолчанию — приём

  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found");
    for (;;);
  }
  display.setTextColor(SSD1306_WHITE);
  draw();
}

void loop() {
  // Кнопка UP — следующий канал (по кругу)
  if (digitalRead(BTN_UP) == LOW) {
    ch = (ch + 1) & 63;
    needRedraw = true;
    delay(250); // антидребезг/антиповтор
  }
  // Кнопка DOWN — предыдущий канал
  if (digitalRead(BTN_DOWN) == LOW) {
    ch = (ch + 63) & 63;
    needRedraw = true;
    delay(250);
  }

  if (needRedraw) {
    draw();
    needRedraw = false;
  }

  // Повторяем команду каждые 500 мс — приёмник «догонит», даже если пакет потерялся
  if (millis() - lastSend > 500) {
    lastSend = millis();
    digitalWrite(DE_RE_PIN, HIGH);
    Serial1.print("CH=");
    Serial1.println(ch);
    digitalWrite(DE_RE_PIN, LOW);
  }
}

void draw() {
  int band = ch >> 3;   // 0..7 → FR1..FR8
  int chan = ch & 7;    // 0..7 → CH1..CH8

  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0, 0);
  display.print(BAND_NAMES[band]);
  display.print(" CH");
  display.println(chan + 1);

  display.setCursor(0, 24);
  display.print(FREQ[band][chan]);
  display.println(" MHz");

  display.setTextSize(1);
  display.setCursor(0, 52);
  display.print("UP/DOWN = channel");
  display.display();
}
